/**
 * Normaliza a chave para busca no dicionário.
 */
function normalizeKey(str) {
    if (!str) return '';
    return str
        .replace(/^Parashat\s+/i, '')
        .toLowerCase()
        .replace(/[^a-z0-9]/g, '');
}

/**
 * Retorna os 5 parágrafos da Parashá em português como um Array de 5 strings sem () ou /.
 */
export function getParashaSummary(parashaName) {
    if (!parashaName) return null;
    const cleanRaw = parashaName.replace(/^Parashat\s+/i, '').replace(/[()\/]/g, '').trim();
    const searchKey = normalizeKey(cleanRaw);

    // 1. Busca direta por chave normalizada
    for (const [key, val] of Object.entries(PARASHA_DESCRIPTIONS)) {
        if (normalizeKey(key) === searchKey) {
            return val.map(s => s.replace(/[()\/]/g, ''));
        }
    }

    // 2. Se for Parashá dupla (contém hífen "-")
    if (cleanRaw.includes('-')) {
        const parts = cleanRaw.split('-').map(p => p.trim());
        const p1Arr = getParashaSummary(parts[0]);
        const p2Arr = getParashaSummary(parts[1]);

        if (p1Arr && p2Arr) {
            return [
                p1Arr[0],
                p1Arr[2] || p1Arr[1],
                p1Arr[4] || p1Arr[3],
                p2Arr[1] || p2Arr[0],
                p2Arr[4] || p2Arr[3]
            ].map(s => s.replace(/[()\/]/g, ''));
        } else if (p1Arr) {
            return p1Arr.map(s => s.replace(/[()\/]/g, ''));
        } else if (p2Arr) {
            return p2Arr.map(s => s.replace(/[()\/]/g, ''));
        }
    }

    return null;
}
